// Cloudflare Worker entry: the OpenNext-built Next.js app plus a Cron Trigger
// that drives background work (campaign sending) through an internal route,
// so all application code stays in the one Next.js bundle.
// @ts-ignore -- generated by `opennextjs-cloudflare build` (absent before the first build)
import { default as handler } from "./.open-next/worker.js";

type Env = { APP_URL?: string; CRON_SECRET?: string };

export default {
  fetch: handler.fetch,

  async scheduled(_controller: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    if (!env.APP_URL || !env.CRON_SECRET) {
      console.error("Cron tick skipped: APP_URL or CRON_SECRET is not set");
      return;
    }
    const req = new Request(new URL("/api/internal/tick", env.APP_URL), {
      method: "POST",
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(
      Promise.resolve(handler.fetch(req, env, ctx)).then(async (res: Response) => {
        if (!res.ok) console.error("Cron tick failed", res.status, await res.text());
      })
    );
  },
};
